@'
import fs from 'node:fs';
import {createHash} from 'node:crypto';
const src=fs.readFileSync('scripts/longitudinal-stress.mjs','utf8').replaceAll('\r\n','\n');
const core=src.slice(src.indexOf('function random('),src.indexOf('if (process.argv.includes("--calibrate"))'));
const sha=createHash('sha256').update(core).digest('hex');
const p=JSON.parse(fs.readFileSync('docs/benchmarks/2026-10-06-longitudinal-stress-protocol.json'));
console.log(JSON.stringify({scoringHash:sha,originalSourceHash:p.sourceHash,coreBytes:core.length}));
fs.copyFileSync('docs/benchmarks/2026-10-06-longitudinal-stress-protocol.json','docs/benchmarks/2026-10-06-longitudinal-stress-protocol-v2.json');
fs.copyFileSync('docs/benchmarks/2026-10-06-longitudinal-stress.json','docs/benchmarks/2026-10-06-longitudinal-stress-v2.json');
'@ | node --input-type=module
